mapper.sql:
o.member_id = #{memberId}
and o.is_red = 0
and o.status in (1, 2, 3, 4, 6, 7)

mapper.select:
select o.pay_amount
from biz_order o
where 
  and o.create_time >= #{from}
  and o.create_time <= #{to}

select ifnull(sum(remain_points), 0)
from biz_point_batch
where member_id = #{memberId}
  and status = 1
  and remain_points > 0
  and expire_time is not null
  and expire_time > #{from}
  and expire_time <= #{to}

mapper.sql:
select 'order' as type, o.order_no as bizNo, concat('订单 ', o.order_no, '（', o.total_qty, ' 件）') as title, o.pay_amount as amount, o.create_time as time, concat('/sales/order/', o.order_id) as linkUrl from biz_order o where o.member_id = #{memberId} and o.is_red = 0 and o.status in (1, 2, 3, 4, 6, 7)
and find_in_set('order', #{typesCsv})
union all select 'borrow' as type, v.borrow_no as bizNo, concat('借阅《', v.title, '》') as title, v.deposit_amount as amount, v.borrow_time as time, concat('/borrow/borrow/', v.borrow_id) as linkUrl from biz_borrow v where v.member_id = #{memberId}
and find_in_set('borrow', #{typesCsv})
union all select 'point' as type, p.ref_no as bizNo, case p.change_type when 1 then '消费获得积分' when 2 then '积分抵扣消费' when 3 then '积分到期清零' else '积分人工调整' end as title, p.points_change / 100 as amount, p.create_time as time, '' as linkUrl from biz_point_log p where p.member_id = #{memberId}
and find_in_set('point', #{typesCsv})
union all select 'stored' as type, s.ref_no as bizNo, case s.amount_type when 1 then '储值充值（本金）' when 2 then '储值充值（赠送金）' when 3 then '储值消费（本金）' when 4 then '储值消费（赠送金）' when 5 then '储值退款（本金）' when 6 then '储值退款（赠送金）' else '储值变动' end as title, s.change_amount as amount, s.create_time as time, '' as linkUrl from biz_stored_value_log s where s.member_id = #{memberId}
and find_in_set('stored', #{typesCsv})

